def load_portrait_catalog():
    try:
        with open(PORTRAIT_MANIFEST_PATH, encoding="utf-8") as manifest_file:
            raw = json.load(manifest_file)
    except (OSError, ValueError, TypeError):
        return {}
    source = raw.get("portraits") if isinstance(raw, dict) else {}
    if not isinstance(source, dict):
        return {}
    allowed_keys = (
        "file", "mime", "commons_title", "source_page", "artist",
        "credit", "license", "license_url", "attribution", "source_kind",
    )
    catalog = {}
    for master_id, value in source.items():
        if not re.fullmatch(r"[a-z0-9_]{1,64}", str(master_id)):
            continue
        if not isinstance(value, dict):
            continue
        file_name = os.path.basename(str(value.get("file") or ""))
        mime = str(value.get("mime") or "")
        if (not file_name or file_name != value.get("file") or
                mime not in ("image/jpeg", "image/png", "image/webp") or
                not os.path.isfile(os.path.join(PORTRAIT_DIR, file_name))):
            continue
        record = {
            key: str(value.get(key) or "").strip()
            for key in allowed_keys
        }
        record["source_kind"] = (
            record["source_kind"] or "wikimedia_commons"
        )
        record["is_placeholder"] = bool(value.get("is_placeholder"))
        record["url"] = (
            "/assets/portraits/" +
            urllib.parse.quote(file_name, safe="._-") +
            "?v=" + urllib.parse.quote(VERSION, safe=".")
        )
        catalog[str(master_id)] = record
    return catalog


PORTRAIT_CATALOG = load_portrait_catalog()


def _valid_packaged_webp(body, width, height):
    """Validate the simple lossy WebP container emitted for this deck."""
    if (len(body) < 30 or body[:4] != b"RIFF" or body[8:12] != b"WEBP"
            or int.from_bytes(body[4:8], "little") + 8 != len(body)
            or body[12:16] != b"VP8 "):
        return False
    chunk_length = int.from_bytes(body[16:20], "little")
    padded = chunk_length + (chunk_length % 2)
    if chunk_length < 10 or 20 + padded != len(body):
        return False
    frame = body[20:20 + chunk_length]
    if frame[3:6] != b"\x9d\x01\x2a":
        return False
    encoded_width = int.from_bytes(frame[6:8], "little") & 0x3FFF
    encoded_height = int.from_bytes(frame[8:10], "little") & 0x3FFF
    return encoded_width == width and encoded_height == height


def load_imagery_catalog():
    """Load the project-local deck as one fail-closed immutable allowlist."""
    try:
        with open(IMAGERY_MANIFEST_PATH, encoding="utf-8") as manifest_file:
            raw = json.load(manifest_file)
    except (OSError, ValueError, TypeError):
        return {}
    cards = raw.get("cards") if isinstance(raw, dict) else None
    if (not isinstance(cards, list) or len(cards) != 24
            or raw.get("card_count") != len(cards)
            or raw.get("therapist_allowlist") != ["freud"]
            or raw.get("presentation_policy") != {
                "descriptions_are_literal": True,
                "psychological_labels": False,
                "max_model_suggestions": 3,
                "suggestions_are_never_selected": True,
                "explicit_user_selection_required": True,
            }
            or raw.get("visual_policy") != {
                "people_or_faces": False,
                "text_or_logos": False,
                "violence_or_sexuality": False,
                "horror_or_threat": False,
            }):
        return {}
    required = {
        "id", "file", "category", "title", "description", "alt",
        "mime", "width", "height", "bytes", "sha256",
    }
    catalog = {}
    total_bytes = 0
    imagery_root = os.path.realpath(IMAGERY_DIR) + os.sep
    try:
        for value in cards:
            if not isinstance(value, dict) or set(value) != required:
                return {}
            card_id = str(value["id"] or "")
            file_name = str(value["file"] or "")
            if (not re.fullmatch(r"[a-z0-9-]{1,64}", card_id)
                    or card_id in catalog
                    or file_name != os.path.basename(file_name)
                    or file_name != card_id + ".webp"
                    or not re.fullmatch(r"[a-z0-9-]{1,64}\.webp", file_name)
                    or value["mime"] != "image/webp"
                    or value["width"] != 768 or value["height"] != 512
                    or type(value["bytes"]) is not int
                    or not 1 <= value["bytes"] <= 500 * 1024
                    or not re.fullmatch(r"[0-9a-f]{64}", value["sha256"])):
                return {}
            path = os.path.join(IMAGERY_DIR, file_name)
            real_path = os.path.realpath(path)
            if (not real_path.startswith(imagery_root)
                    or os.path.islink(path) or not os.path.isfile(path)):
                return {}
            with open(path, "rb") as image_file:
                body = image_file.read(500 * 1024 + 1)
            if (len(body) != value["bytes"]
                    or not _valid_packaged_webp(
                        body, value["width"], value["height"])
                    or hashlib.sha256(body).hexdigest() != value["sha256"]):
                return {}
            total_bytes += len(body)
            if total_bytes > 8 * 1024 * 1024:
                return {}
            record = {
                key: str(value[key]).strip()
                for key in ("id", "file", "category", "title",
                            "description", "alt", "mime", "sha256")
            }
            if (not all(record[key] for key in (
                    "category", "title", "description", "alt"))
                    or any(len(record[key]) > limit for key, limit in (
                        ("category", 40), ("title", 80),
                        ("description", 500), ("alt", 300)))
                    or any("http://" in record[key].lower()
                           or "https://" in record[key].lower()
                           for key in ("title", "description", "alt"))):
                return {}
            record.update({
                "width": value["width"], "height": value["height"],
                "bytes": value["bytes"],
                "url": "/assets/imagery/" +
                       urllib.parse.quote(file_name, safe="._-") +
                       "?v=" + urllib.parse.quote(VERSION, safe="."),
            })
            catalog[card_id] = record
    except (OSError, KeyError, TypeError, ValueError):
        return {}
    return catalog if len(catalog) == 24 else {}


IMAGERY_CATALOG = load_imagery_catalog()

