# Koçlar ALL_MASTERS'a bilinçli olarak eklenmez: klinik katalog sözleşmeleri
# (ses, parmak izi, portre, harita) yalnız kurucu ustaları kapsar.


def known_master(master_id):
    """Konuşma açılabilen tüm kişilikler (klinik katalog + koçlar)."""
    return master_id in ALL_MASTERS or master_id in COACHES

def is_coach(master_id):
    return master_id in COACHES

def is_philosopher(master_id):
    return master_id in PHILOSOPHERS

def master_record(master_id, fallback=True):
    record = ALL_MASTERS.get(master_id) or COACHES.get(master_id)
    if record is None and fallback:
        return THERAPISTS["freud"]
    return record

def master_name(master_id):
    record = master_record(master_id, fallback=False)
    return record["name"] if record else str(master_id or "")

