def experiential_stage(stage_id, label, aim, prompt,
                       preferred_slots=(), choices=(), choice_actions=()):
    """Published, serialisable micro-stage used by experiential protocols."""
    if choice_actions and len(choice_actions) != len(choices):
        raise ValueError("choice_actions must match choices")
    return {
        "id": stage_id,
        "label": label,
        "aim": aim,
        "prompt": prompt,
        "preferred_slots": list(preferred_slots),
        "choices": list(choices),
        # Machine-readable actions deliberately travel beside localized
        # labels. Clients must never infer a safety transition from wording.
        "choice_actions": list(choice_actions),
    }


# This catalogue is deliberately separate from the linear protocols.  The
