def philosophy_dialogue_closing(philosopher_id):
    """Return one short, deterministic thinker-specific dialogue close."""
    signature = PHILOSOPHY_DIALOGUE_CLOSINGS.get(philosopher_id)
    if not signature:
        signature = (
            "Açık kalan ayrımı kesin bir sonuca zorlamadan düşünce "
            "defterinde tutalım."
        )
    return "Bugünkü felsefi diyaloğu burada bırakalım. {}".format(signature)

def therapy_lesson_closing(therapist_id):
    """Return one short, deterministic founder-specific teaching close."""
    signature = THERAPY_LESSON_CLOSINGS.get(therapist_id)
    if not signature:
        signature = (
            "Bugün açılan temel ayrımı kesin bir sonuca zorlamadan öğrenme "
            "defterinde tutalım."
        )
    return "Bugünkü dersi burada tamamlayalım. {}".format(signature)


