# The TUS planner consumes a packaged metadata allowlist, never the question
# bank itself.  Keeping the protocol separate from the general ADHD surfaces
# makes it possible for every native client to reject a mismatched payload.
ADHD_TUS_PROTOCOL = "adhd_tus_planner_v1"
ADHD_TUS_CHAT_PROTOCOL = "adhd_tus_chat_v1"
ADHD_TUS_CHAT_KINDS = frozenset({
    "question", "plan_ready", "active_step", "paused", "completed",
    "cancelled",
})
ADHD_TUS_CATALOG_PROTOCOL = "divan_tus_catalog_v1"
ADHD_TUS_CATALOG_SCHEMA_FINGERPRINT = (
    "sha256:57905d2005824afbd9bd40468231512b433b1e3a9cce955000e3f4239ec07b82"
)
ADHD_TUS_CATALOG_MAX_BYTES = 8 * 1024 * 1024
ADHD_TUS_OPTION_LIMIT = 40
ADHD_TUS_PLAN_MAX_STEPS = 20
ADHD_TUS_MAX_STEP_MINUTES = 20
ADHD_TUS_TIME_OPTIONS = (5, 15, 25, 45)
ADHD_TUS_CUSTOM_TIME_MIN = 5
ADHD_TUS_CUSTOM_TIME_MAX = 180
ADHD_TUS_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:\-]{0,127}$")
ADHD_TUS_RAW_KEYS = {
    "answer", "answers", "choice", "choices", "content", "contents",
    "explanation", "explanations", "option", "options", "prompt",
    "question", "questions", "question_text", "raw", "sentence",
    "sentences", "sentence_text", "solution", "solutions", "stem", "text",
}
ADHD_TUS_PHASES = (
    "activity", "lesson", "reading_area", "question_area",
    "available_time", "start_friction",
)
