# The detector may only name concepts already present in Divan's reviewed
# Schema Therapy catalogues.  Labels are always derived here; a model cannot
# invent a clinical-sounding label and smuggle it into a candidate card.
def _build_schema_candidate_catalog():
    """Modele sunulan şema kataloğu: 18 erken dönem uyumsuz şemanın tamamı.

    Eskiden yalnız `THERAPY_CONCEPTS["young"]` içindeki 4 şema sunuluyordu;
    model kalan 14'ünü adlandıramadığı için en yakın etikete zorlanıyordu.
    Kaynak artık `SCHEMA_DEFINITIONS`.

    Eski anahtarlar (`schema_abandonment` gibi) kalıcıdır: mevcut kayıtlar,
    eşitleme ve kullanıcı kararları onlara bağlı, yeniden adlandırılmaz.
    """
    legacy = {
        row["key"]: row["name"]
        for row in THERAPY_CONCEPTS.get("young", ())
        if (str(row.get("key") or "").startswith("schema_")
            or row.get("key") == "unrelenting_standards")
    }
    catalog = dict(legacy)
    # Eski anahtarların hangi tanıma karşılık geldiği: aynı şema iki ayrı
    # kimlikle sunulup modelin ikisini farklı sanmasını engeller.
    covered = set()
    for key in legacy:
        covered.add(key[len("schema_"):] if key.startswith("schema_") else key)
    for row in SCHEMA_DEFINITIONS:
        if row["id"] in covered:
            continue
        catalog[row["id"]] = row["label"]
    return catalog


SCHEMA_CANDIDATE_CATALOG = _build_schema_candidate_catalog()
SCHEMA_MODE_CANDIDATE_CATALOG = {
    row["id"]: row["label"]
    for row in SCHEMA_STRATEGY_LIBRARY
    if row["id"] not in ("healthy_adult", "happy_child")
}


def schema_mode_conversation_eligible(conv):
    return bool(
        conv and conv["mode"] == "terapi" and conv["therapist"] == "young"
        and (conv["submode"] or "") == "" and not conv["is_guest"])


def schema_mode_state(connection, conv_id):
    row = connection.execute(
        "SELECT schema_mode_enabled,schema_mode_initialized,"
        "schema_mode_enrolled_after_message_id,"
        "schema_mode_provider,schema_mode_model,"
        "updated FROM session_meta WHERE conv=?", (conv_id,)).fetchone()
    preference_enabled = bool(row and row["schema_mode_enabled"])
    initialized = bool(row and row["schema_mode_initialized"])
    consent_provider = str(row["schema_mode_provider"] or "") if row else ""
    consent_model = str(row["schema_mode_model"] or "") if row else ""
    current_provider, current_model = _configured_provider_model_snapshot()
    provider_matches = bool(
        initialized and consent_provider == current_provider
        and consent_model == current_model)
    effective_enabled = bool(preference_enabled and provider_matches)
    return {
        # The synced boolean is only a preference.  Text may be sent for
        # Schema analysis on this device only after the local provider/model
        # disclosure has been confirmed explicitly.
        "enabled": effective_enabled,
        "preference_enabled": preference_enabled,
        "initialized": initialized,
        "pending_device_confirmation": bool(
            preference_enabled and not initialized),
        "pending_provider_confirmation": bool(
            preference_enabled and initialized and not provider_matches),
        "consent_provider": consent_provider,
        "consent_model": consent_model,
        "enrolled_after_message_id": int(
            row["schema_mode_enrolled_after_message_id"] or 0)
            if row else 0,
        "updated": str(row["updated"] or "") if row else "",
    }


def schema_mode_public(connection, conv):
    state = schema_mode_state(connection, conv["id"])
    eligible = schema_mode_conversation_eligible(conv)
    reason = ""
    if not eligible:
        reason = "young_therapy_required"
    elif conv["safety_hold"]:
        reason = "safety_hold"
    elif conv["ended"] or conv["archived_at"]:
        reason = "conversation_closed"
    elif state["pending_device_confirmation"]:
        reason = "device_confirmation_required"
    elif state["pending_provider_confirmation"]:
        reason = "provider_confirmation_required"
    return {
        "enabled": state["enabled"],
        "preference_enabled": state["preference_enabled"],
        "pending_device_confirmation": state[
            "pending_device_confirmation"],
        "pending_provider_confirmation": state[
            "pending_provider_confirmation"],
        "can_enable": bool(
            eligible and not conv["safety_hold"]
            and not conv["ended"] and not conv["archived_at"]),
        "reason": reason,
        "updated": state["updated"],
    }


def schema_mode_consent_error(state, provider_id=None, model_id=None):
    """Stable reason why Schema text may not use this provider snapshot."""
    if not state["preference_enabled"]:
        return "schema_mode_off"
    if state["pending_device_confirmation"]:
        return "device_confirmation_required"
    if state["pending_provider_confirmation"]:
        return "provider_confirmation_required"
    if (provider_id not in (None, "") and (
            str(provider_id) != state["consent_provider"]
            or (str(model_id or "") != state["consent_model"]
                and not (state["consent_model"] == "auto"
                         and is_local_provider(
                             state["consent_provider"]))))):
        return "provider_changed"
    return "" if state["enabled"] else "schema_mode_off"


def ensure_schema_mode_local_enrollment(connection, conv,
                                        before_message_id=None):
    """Return local consent state without turning synced preference into it.

    The name is retained for callers from the sync/recovery era.  Deliberately
    do *not* initialize here: a different device may use a different model or
    provider.  Only ``set_schema_mode(..., True)`` may establish the local
    disclosure consent and future-only watermark.
    """
    del before_message_id
    return schema_mode_state(connection, conv["id"])


def initialize_synced_schema_modes():
    # Compatibility hook used by startup and /api/sync/join.  Report pending
    # device confirmations, but never convert them into provider consent.
    with db() as connection:
        return int(connection.execute(
            "SELECT COUNT(*) AS n FROM session_meta WHERE "
            "schema_mode_enabled=1 AND schema_mode_initialized=0"
        ).fetchone()["n"] or 0)


def reconcile_disabled_schema_paths():
    """Pause work whose local provider-bound Schema consent is ineffective.

    Consent withdrawal is a control transition, not a bare path flag.  Keep
    path/step/checkpoint and every local experiential link/run in the same
    grounded paused state so no later dashboard or sync reconciliation can
    expose an apparently live deep prompt.
    """
    with DATA_WRITE_LOCK:
        with db() as connection:
            rows = connection.execute(
                "SELECT p.* FROM schema_paths p "
                "WHERE p.status='active'").fetchall()
            paused = 0
            for path in rows:
                if schema_mode_state(connection, path["conv"])["enabled"]:
                    continue
                if int(path["flow_version"] or 0) >= 4:
                    _schema_v4_pause_chat_path(
                        connection, path, reason="schema_mode_off")
                else:
                    connection.execute(
                        "UPDATE schema_paths SET status='paused',"
                        "revision=revision+1,updated=? WHERE id=? "
                        "AND status='active'", (now(), path["id"]))
                paused += 1
            return paused


def schema_path_method_rows():
    rows = []
    for method in method_records("young"):
        rows.append({
            "method_id": method["node_id"],
            "node_id": method["node_id"],
            "name": method["name"],
            "description": method["description"],
            "interaction_mode": method["interaction_mode"],
            "risk_level": method["risk_level"],
            "requires_consent": True,
            "requires_precheck": method["risk_level"] == "enhanced",
            "process_tags": list(method["process_tags"]),
        })
    return rows


SCHEMA_FOCUS_MAX_CANDIDATES = 3
# Odak sunmadan önce görüşmede birikmesi gereken en az tamamlanmış tur.
# Erken etiketleme tanımak değil kapatmaktır: eşik dolmadan mod adı geçmez.
SCHEMA_FOCUS_MIN_TURNS = 3


def schema_focus_library_row(mode_key):
    """Kütüphanedeki mod kaydı; bilinmeyen anahtar için None."""
    for row in SCHEMA_STRATEGY_LIBRARY:
        if row["id"] == mode_key:
            return row
    return None


def schema_focus_candidate_card(mode_key, evidence=""):
    """Kullanıcıya gösterilecek aday kartı.

    Etiket ve açıklama daima sunucudaki kütüphaneden türetilir; model
    klinik görünümlü bir ad uydurup karta sokamaz. `evidence` yalnız
    kullanıcının kendi cümlesidir.
    """
    row = schema_focus_library_row(mode_key)
    if row is None:
        return None
    return {
        "mode_key": row["id"],
        "label": row["label"],
        "chair_label": row.get("chair_label", row["label"]),
        "group": row.get("group", ""),
        # Başa çıkma tarzı: teslim / kaçınma / aşırı telafi. Aynı şema
        # farklı tarzlarla görünebilir; tarz kişilik değil, o andaki tepki.
        "coping_style": SCHEMA_COPING_STYLE_BY_MODE.get(row["id"], ""),
        "recognize": row.get("recognize", ""),
        "question": row.get("question", ""),
        # Gerekçe kullanıcının kendi cümlesidir; boş kalabilir.
        "evidence": " ".join(str(evidence or "").split())[
            :SCHEMA_PATH_TEXT_LIMIT],
    }


def schema_focus_offerable_modes():
    """Odak olarak sunulabilecek mod anahtarları.

    Sağlıklı Yetişkin ve Mutlu Çocuk bir *sorun odağı* değildir; onlar
    güçlendirilecek kaynaklardır, üzerinde çalışılacak mod değil.
    """
    return tuple(
        row["id"] for row in SCHEMA_STRATEGY_LIBRARY
        if row["id"] not in ("healthy_adult", "happy_child"))


def schema_focus_active_offer(connection, path_id):
    return connection.execute(
        "SELECT * FROM schema_focus_offers WHERE path=? AND status='offered' "
        "ORDER BY id DESC LIMIT 1", (path_id,)).fetchone()


def schema_focus_chosen(connection, path_id):
    return connection.execute(
        "SELECT * FROM schema_focus_offers WHERE path=? AND status='chosen' "
        "ORDER BY id DESC LIMIT 1", (path_id,)).fetchone()


def schema_auto_focus_candidates(connection, conv_id, limit=None):
    """Bu görüşmede kanıtlanmış mod adaylarından odak kartları üret.

    Model her turda mod tespiti yapıyor ve bunu `psych_claims.mode_key`
    alanına yazıyor; ama bu bilgi hiçbir yerde odak önerisine
    dönüşmüyordu. Burada yalnız *zaten kanıtlanmış* modlar kart olur:
    yeni bir çıkarım yapılmaz, katalog dışına çıkılmaz.
    """
    limit = SCHEMA_FOCUS_MAX_CANDIDATES if limit is None else limit
    offerable = set(schema_focus_offerable_modes())
    rows = connection.execute(
        "SELECT c.mode_key,c.statement,m.content AS user_content "
        "FROM psych_claims c "
        "JOIN psych_claim_evidence e ON e.claim=c.id "
        "AND e.relation='supports' AND e.review_status='accepted' "
        "JOIN psych_observations o ON o.id=e.observation AND o.conv=? "
        "JOIN messages m ON m.id=o.source_message AND m.conv=o.conv "
        "AND m.role='user' AND m.delivery_status='completed' "
        "JOIN chat_requests q ON q.conv=o.conv AND q.user_message=m.id "
        "AND q.status='completed' "
        "JOIN messages a ON a.id=q.assistant_message AND a.conv=q.conv "
        "AND a.role='assistant' AND a.delivery_status='completed' "
        "WHERE c.source_conv=? AND c.therapist='young' "
        "AND c.mode_key IS NOT NULL AND c.mode_key<>'' "
        "AND c.scope NOT IN ('private','excluded') AND c.sensitive=0 "
        "AND NOT EXISTS(SELECT 1 FROM safety_events s WHERE s.conv=q.conv "
        "AND s.source_message=q.user_message) "
        "ORDER BY c.updated DESC,c.id DESC,e.id DESC", (conv_id, conv_id)
    ).fetchall()
    cards = []
    seen = set()
    for row in rows:
        key = str(row["mode_key"] or "")
        if key not in offerable or key in seen:
            continue
        seen.add(key)
        card = schema_focus_candidate_card(
            key, str(row["user_content"] or ""))
        if card is None:
            continue
        cards.append(card)
        if len(cards) >= limit:
            break
    return cards


def ensure_schema_focus_offer(connection, conv_id, path):
    """Odak aşamasına girildiğinde öneriyi kendiliğinden hazırla.

    `offer_focus` ucu vardı ama hiçbir yerden çağrılmıyordu; bu yüzden
    "Neyi çalışalım?" kartı gerçek kullanımda hiç belirmiyordu. Burada
    öneri sunucu tarafında, kanıta dayanarak kurulur.

    Erken etiketleme yasağı korunur: eşik dolmadan kart çıkmaz.
    Kullanıcı "hiçbiri" derse (declined) yeniden dayatılmaz.
    """
    if not path or path["phase"] != "focus":
        return False
    if path["status"] not in SCHEMA_PATH_ACTIVE_STATUSES:
        return False
    if schema_focus_active_offer(connection, path["id"]):
        return False
    if schema_focus_chosen(connection, path["id"]):
        return False
    # Kullanıcı bu yolda öneriyi bir kez geri çevirdiyse tekrar sunma.
    declined = connection.execute(
        "SELECT 1 FROM schema_focus_offers WHERE path=? AND status='declined' "
        "LIMIT 1", (path["id"],)).fetchone()
    if declined:
        return False
    if schema_completed_turn_count(connection, conv_id) < (
            SCHEMA_FOCUS_MIN_TURNS):
        return False
    cards = schema_auto_focus_candidates(connection, conv_id)
    if not cards:
        return False
    stamp = now()
    connection.execute(
        "INSERT INTO schema_focus_offers(path,conv,candidates_json,status,"
        "created,updated) VALUES(?,?,?,'offered',?,?)",
        (path["id"], conv_id,
         json.dumps(cards, ensure_ascii=False), stamp, stamp))
    return True


def schema_focus_public(connection, path_id):
    """Odak aşamasının kullanıcıya açık durumu."""
    if not path_id:
        return {"offer": None, "chosen": None}
    offer = schema_focus_active_offer(connection, path_id)
    chosen = schema_focus_chosen(connection, path_id)
    offer_payload = None
    if offer is not None:
        try:
            candidates = json.loads(offer["candidates_json"])
        except (TypeError, ValueError):
            candidates = []
        offer_payload = {
            "id": offer["id"],
            "candidates": candidates,
            "created": offer["created"],
        }
    chosen_payload = None
    if chosen is not None:
        chosen_payload = {
            "mode_key": chosen["chosen_key"],
            "label": chosen["chosen_label"],
            "created": chosen["updated"],
        }
    return {"offer": offer_payload, "chosen": chosen_payload}


SCHEMA_ORIGIN_CONFIDENCES = ("reported", "uncertain", "unknown")
# Büyütme basamağı sayısı: yaş yaş çıkmak için birkaç durak yeter.
SCHEMA_GROWTH_MAX_STAGES = 6


def schema_origin_row(connection, path_id):
    if not path_id:
        return None
    return connection.execute(
        "SELECT * FROM schema_origin WHERE path=? AND status='active'",
        (path_id,)).fetchone()


def schema_origin_public(connection, path_id):
    """Kökenin kullanıcıya açık hâli; yoksa boş kabuk."""
    row = schema_origin_row(connection, path_id)
    if row is None:
        return {
            "recorded": False, "age": None, "age_range": "",
            "scene": "", "unmet_need": "", "confidence": "unknown",
        }
    return {
        "recorded": True,
        "age": row["age_reported"],
        "age_range": row["age_range"],
        "scene": row["scene"],
        "unmet_need": row["unmet_need"],
        "confidence": row["confidence"],
        "updated": row["updated"],
    }


def schema_growth_rows(connection, path_id):
    if not path_id:
        return []
    return connection.execute(
        "SELECT * FROM schema_growth WHERE path=? AND status='active' "
        "ORDER BY seq,id",
        (path_id,)).fetchall()


def schema_growth_public(connection, path_id):
    """Basamaklar ve tamamlanma durumu.

    Bir basamak ancak `then_response` ve `now_response` birlikte
    doluyken karşılaştırılabilir sayılır: tek yanı olan basamak
    "eskisi ile bugünü yan yana görme" işini yapmaz.
    """
    rows = schema_growth_rows(connection, path_id)
    stages = []
    for row in rows:
        stages.append({
            "id": row["id"],
            "seq": row["seq"],
            "age": row["stage_age"],
            "label": row["stage_label"],
            "then_response": row["then_response"],
            "now_response": row["now_response"],
            "difference": row["difference"],
            "comparable": bool(
                str(row["then_response"] or "").strip()
                and str(row["now_response"] or "").strip()),
        })
    return {
        "stages": stages,
        "comparable_count": sum(1 for s in stages if s["comparable"]),
        "max_stages": SCHEMA_GROWTH_MAX_STAGES,
    }


def healthy_adult_marks_public(connection, conv_id, limit=5):
    """Sağlıklı Yetişkin kanıtları.

    Sayı bir hedef değildir ve kota olarak gösterilmez; yalnız
    "bu ses burada da göründü" demek için tutulur.
    """
    rows = connection.execute(
        "SELECT h.*,u.public_id AS source_user_public_id,"
        "a.public_id AS source_assistant_public_id "
        "FROM healthy_adult_marks h "
        "LEFT JOIN messages u ON u.id=h.source_message AND u.conv=h.conv "
        "LEFT JOIN messages a ON a.id=h.source_assistant_message "
        "AND a.conv=h.conv WHERE h.conv=? AND h.status='active' "
        "ORDER BY h.id DESC LIMIT ?",
        (conv_id, int(limit))).fetchall()
    total = int(connection.execute(
        "SELECT COUNT(*) AS n FROM healthy_adult_marks WHERE conv=? "
        "AND status='active'",
        (conv_id,)).fetchone()["n"] or 0)
    return {
        "count": total,
        "recent": [
            {"id": row["id"], "public_id": str(row["public_id"] or ""),
             "evidence": row["evidence"], "source": row["source"],
             "source_user_message_id": row["source_message"],
             "source_user_message_public_id": str(
                 row["source_user_public_id"] or ""),
             "source_assistant_message_id":
                 row["source_assistant_message"],
             "source_assistant_message_public_id": str(
                 row["source_assistant_public_id"] or ""),
             "created": row["created"]}
            for row in rows],
    }


def schema_transfer_public(connection, path_id):
    if not path_id:
        return {"recorded": False}
    row = connection.execute(
        "SELECT t.*,u.public_id AS source_user_public_id,"
        "a.public_id AS source_assistant_public_id,"
        "tu.public_id AS trigger_user_public_id,"
        "ta.public_id AS trigger_assistant_public_id "
        "FROM schema_transfer_records t "
        "LEFT JOIN messages u ON u.id=t.source_user_message "
        "AND u.conv=t.conv "
        "LEFT JOIN messages a ON a.id=t.source_assistant_message "
        "AND a.conv=t.conv "
        "LEFT JOIN messages tu ON tu.id=t.trigger_source_user_message "
        "AND tu.conv=t.conv "
        "LEFT JOIN messages ta ON ta.id=t.trigger_source_assistant_message "
        "AND ta.conv=t.conv WHERE t.path=? AND t.status='active'",
        (path_id,)).fetchone()
    if row is None:
        return {"recorded": False}
    return {
        "recorded": True,
        "id": int(row["id"]), "public_id": str(row["public_id"] or ""),
        "source_user_message_id": int(row["source_user_message"]),
        "source_user_message_public_id": str(
            row["source_user_public_id"] or ""),
        "source_assistant_message_id": int(row["source_assistant_message"]),
        "source_assistant_message_public_id": str(
            row["source_assistant_public_id"] or ""),
        "trigger_source_user_message_id": int(
            row["trigger_source_user_message"]),
        "trigger_source_user_message_public_id": str(
            row["trigger_user_public_id"] or ""),
        "trigger_source_assistant_message_id": (
            int(row["trigger_source_assistant_message"])
            if row["trigger_source_assistant_message"] else None),
        "trigger_source_assistant_message_public_id": str(
            row["trigger_assistant_public_id"] or ""),
        "trigger": row["trigger_text"],
        "healthy_adult_response": row["healthy_adult_response"],
        "planned_action": row["planned_action"],
        "support_choice": row["support_choice"],
        "predicted_result": row["predicted_result"],
        "observed_result": row["observed_result"],
        "created": row["created"], "updated": row["updated"],
    }


def schema_active_path_row(connection, conv_id):
    """Görüşmenin etkin şema çalışma yolu; yoksa None."""
    return connection.execute(
        "SELECT * FROM schema_paths WHERE conv=? AND status IN "
        "('active','paused') ORDER BY id DESC LIMIT 1",
        (conv_id,)).fetchone()


def schema_chosen_mode_label(connection, conv_id):
    """Kullanıcının odak olarak seçtiği modun adı; yoksa boş."""
    path = schema_active_path_row(connection, conv_id)
    if path is None:
        return ""
    chosen = schema_focus_chosen(connection, path["id"])
    return str(chosen["chosen_label"] or "") if chosen else ""


def schema_chair_focus_context(connection, conv_id):
    """Sandalye rehberliğine seçili mod, köken ve Sağlıklı Yetişkin izleri.

    Köken yalnız kullanıcının anlattığıyla doldurulur; boşsa boş kalır ve
    usta yaş uydurmaz.
    """
    path = schema_active_path_row(connection, conv_id)
    if path is None:
        return ""
    chosen = schema_focus_chosen(connection, path["id"])
    if chosen is None:
        return ""
    lines = [
        "## Bu sandalye çalışmasının odağı",
        "Kullanıcı üzerinde çalışmayı seçtiği mod: {}.".format(
            chosen["chosen_label"]),
    ]
    origin = schema_origin_public(connection, path["id"])
    if origin["recorded"] and origin["confidence"] != "unknown":
        parts = []
        if origin["age"] is not None:
            parts.append("yaş {}".format(origin["age"]))
        elif origin["age_range"]:
            parts.append("yaş aralığı {}".format(origin["age_range"]))
        if origin["scene"]:
            parts.append("sahne: {}".format(
                clip_context_text(origin["scene"], 300)))
        if origin["unmet_need"]:
            parts.append("karşılanmayan ihtiyaç: {}".format(
                clip_context_text(origin["unmet_need"], 200)))
        if parts:
            lines.append(
                "Kullanıcının kendi anlattığı köken — {}. Bunu olduğu gibi "
                "kullan; ayrıntı ekleme, tarih veya sahne uydurma.".format(
                    "; ".join(parts)))
    else:
        lines.append(
            "Köken kullanıcı tarafından anlatılmadı. Yaş, tarih veya "
            "çocukluk sahnesi UYDURMA; çalışma yaşsız yürür.")
    marks = healthy_adult_marks_public(connection, conv_id, limit=2)
    if marks["count"]:
        recent = marks["recent"][0]["evidence"] if marks["recent"] else ""
        lines.append(
            "Sağlıklı Yetişkin sesi bu görüşmede {} kez göründü{}. Bunu "
            "kaynak olarak hatırlat; puan veya hedef gibi sunma.".format(
                marks["count"],
                "; en son: \"{}\"".format(
                    clip_context_text(recent, 160)) if recent else ""))
    return "\n".join(lines)


def schema_completed_turn_count(connection, conv_id):
    """Count only durable, normal completed chat request pairs."""
    return int(_living_map_completed_user_meta(
        connection, conv_id)["source_count"] or 0)


def schema_completed_turns_through(connection, conv_id, user_message_id=None,
                                   inclusive=True):
    """Count authoritative safe pairs up to one user source, if supplied."""
    boundary = ""
    params = [conv_id]
    if user_message_id is not None:
        boundary = "AND q.user_message{}? ".format("<=" if inclusive else "<")
        params.append(int(user_message_id))
    row = connection.execute(
        "SELECT COUNT(DISTINCT q.user_message) AS n FROM chat_requests q "
        "JOIN messages u ON u.id=q.user_message AND u.conv=q.conv "
        "AND u.role='user' AND u.delivery_status='completed' "
        "JOIN messages a ON a.id=q.assistant_message AND a.conv=q.conv "
        "AND a.role='assistant' AND a.delivery_status='completed' "
        "WHERE q.conv=? AND q.status='completed' " + boundary +
        "AND NOT EXISTS(SELECT 1 FROM safety_events s WHERE s.conv=q.conv "
        "AND s.source_message=q.user_message)", params).fetchone()
    return int(row["n"] or 0)


def schema_claim_evidence_state(connection, claim_id, conv_id):
    row = connection.execute(
        """
        SELECT
          COUNT(DISTINCT CASE WHEN e.review_status='accepted' THEN e.id END)
            AS accepted_count,
          COUNT(DISTINCT CASE WHEN e.review_status='pending' THEN e.id END)
            AS pending_count,
          COUNT(DISTINCT CASE WHEN e.review_status IN ('accepted','pending')
            THEN e.id END) AS reviewable_count
        FROM psych_claim_evidence e
        JOIN psych_observations o ON o.id=e.observation
        JOIN messages m ON m.id=o.source_message
        WHERE e.claim=? AND e.relation='supports' AND o.conv=?
          AND m.conv=? AND m.role='user'
        """, (claim_id, conv_id, conv_id)).fetchone()
    completed = connection.execute(
        """
        SELECT
          COUNT(DISTINCT CASE WHEN e.review_status='accepted'
            THEN e.id END) AS accepted_count,
          COUNT(DISTINCT CASE WHEN e.review_status='pending'
            THEN e.id END) AS pending_count,
          COUNT(DISTINCT CASE WHEN e.review_status IN ('accepted','pending')
            THEN e.id END) AS reviewable_count
        FROM psych_claim_evidence e
        JOIN psych_observations o ON o.id=e.observation
        JOIN messages m ON m.id=o.source_message
        JOIN chat_requests q ON q.conv=o.conv AND q.user_message=m.id
          AND q.status='completed'
        JOIN messages a ON a.id=q.assistant_message AND a.conv=q.conv
          AND a.role='assistant' AND a.delivery_status='completed'
        WHERE e.claim=? AND e.relation='supports'
          AND e.review_status IN ('accepted','pending')
          AND o.conv=? AND m.conv=?
          AND m.role='user' AND m.delivery_status='completed'
          AND NOT EXISTS(SELECT 1 FROM safety_events s
            WHERE s.conv=q.conv AND s.source_message=q.user_message)
        """, (claim_id, conv_id, conv_id)).fetchone()
    return {
        "accepted": int(row["accepted_count"] or 0),
        "accepted_completed": int(completed["accepted_count"] or 0),
        "pending": int(row["pending_count"] or 0),
        "reviewable": int(row["reviewable_count"] or 0),
        "pending_completed": int(completed["pending_count"] or 0),
        "reviewable_completed": int(completed["reviewable_count"] or 0),
    }


def schema_claim_user_sources(connection, claim_id, conv_id, relation):
    rows = connection.execute(
        """
        SELECT e.id,e.relation,e.review_status,e.created,
               m.id AS message_id,m.content,m.created AS message_created
        FROM psych_claim_evidence e
        JOIN psych_observations o ON o.id=e.observation
        JOIN messages m ON m.id=o.source_message
        WHERE e.claim=? AND o.conv=? AND m.conv=? AND m.role='user'
          AND e.relation=?
        ORDER BY m.id,e.id
        """, (claim_id, conv_id, conv_id, relation)).fetchall()
    valid_rows = []
    for row in rows:
        pair, _error = completed_normal_turn(
            connection, conv_id, row["message_id"])
        if pair:
            valid_rows.append(row)
    return [{
        "evidence_id": row["id"],
        "message_id": row["message_id"],
        "relation": row["relation"],
        "review_status": row["review_status"],
        "excerpt": clip_context_text(row["content"], 700),
        "source_created": row["message_created"],
    } for row in valid_rows]


def schema_candidate_row(connection, conv_id, claim_id):
    row = connection.execute(
        "SELECT * FROM psych_claims WHERE id=? AND source_conv=? "
        "AND therapist='young' AND claim_type='schema_hypothesis'",
        (claim_id, conv_id)).fetchone()
    if not row:
        return None
    if (row["schema_key"] in SCHEMA_CANDIDATE_CATALOG
            or row["mode_key"] in SCHEMA_MODE_CANDIDATE_CATALOG):
        return row
    # Preserve an already-started legacy path, but never turn an old/free-form
    # map hypothesis into a new Schema Path button.
    legacy_path = connection.execute(
        "SELECT 1 FROM schema_paths WHERE conv=? AND claim=? LIMIT 1",
        (conv_id, claim_id)).fetchone()
    return row if legacy_path else None


def public_schema_candidate(connection, row, conv_id):
    evidence = schema_claim_evidence_state(connection, row["id"], conv_id)
    user_sources = schema_claim_user_sources(
        connection, row["id"], conv_id, "supports")
    counter_sources = schema_claim_user_sources(
        connection, row["id"], conv_id, "counterexample")
    source_turns = []
    for source in user_sources:
        # Only evidence which can still be explicitly accepted may own the
        # visible candidate card and its deterministic work identity. Keep
        # rejected rows in the audit/source list, but never make one the
        # mutation authority merely because it is chronologically first.
        if source["review_status"] not in ("accepted", "pending"):
            continue
        pair, _error = completed_normal_turn(
            connection, conv_id, source["message_id"])
        if not pair:
            continue
        public_rows = connection.execute(
            "SELECT id,public_id FROM messages WHERE id IN (?,?)",
            (pair["user_message"], pair["assistant_message"])).fetchall()
        public_ids = {int(item["id"]): str(item["public_id"] or "")
                      for item in public_rows}
        source_turns.append({
            "user_message_id": int(pair["user_message"]),
            "user_message_public_id": public_ids.get(
                int(pair["user_message"]), ""),
            "assistant_message_id": int(pair["assistant_message"]),
            "assistant_message_public_id": public_ids.get(
                int(pair["assistant_message"]), ""),
            "user_excerpt": clip_context_text(pair["user_content"], 700),
            "assistant_excerpt": clip_context_text(
                pair["assistant_content"], 700),
            "completed": True,
        })
    source_invalidated = bool(
        evidence["reviewable_completed"] < 1
        or row["scope"] in ("private", "excluded")
        or row["sensitive"])
    if source_invalidated:
        # A candidate is only a view over its still-eligible source turn.  If
        # that turn later becomes unsafe/incomplete (or the user makes the
        # inference private), do not keep exposing model-derived clinical
        # text merely because the local claim row still exists for audit and
        # active-path continuity.
        user_sources = []
        counter_sources = []
        source_turns = []
    active_path = schema_active_path_row(connection, conv_id)
    used_for_path = bool(connection.execute(
        "SELECT 1 FROM schema_paths WHERE conv=? AND claim=? "
        "AND flow_version>=4 LIMIT 1", (conv_id, row["id"])).fetchone())
    locked_by_other = bool(
        active_path and int(active_path["claim"]) != int(row["id"]))
    deferred = bool(row["status"] == "deferred" or locked_by_other)
    decision_state = "invalidated" if source_invalidated else {
        "candidate": "pending",
        "deferred": "deferred",
        "confirmed": "accepted",
        "partial": "accepted",
        "contextual": "accepted",
        "rejected": "dismissed",
        "private": "private",
    }.get(row["status"], row["status"])
    hypothesis_parts = []
    if row["schema_key"] in SCHEMA_CANDIDATE_CATALOG:
        hypothesis_parts.append(
            SCHEMA_CANDIDATE_CATALOG[row["schema_key"]])
    if row["mode_key"] in SCHEMA_MODE_CANDIDATE_CATALOG:
        hypothesis_parts.append(
            SCHEMA_MODE_CANDIDATE_CATALOG[row["mode_key"]] + " modu")
    work_public_id = ""
    if source_turns:
        conv_row = connection.execute(
            "SELECT public_id FROM conversations WHERE id=?", (conv_id,)
        ).fetchone()
        source = source_turns[0]
        if conv_row and conv_row["public_id"]:
            work_public_id = _schema_natural_public_id(
                "candidate", conv_row["public_id"],
                schema_clinical_generation(connection, conv_id),
                source["user_message_public_id"],
                source["assistant_message_public_id"],
                row["schema_key"] or "-", row["mode_key"] or "-")
    return {
        "id": row["id"],
        "public_id": row["public_id"],
        # The raw psych-claim id is device-local graph history. This natural
        # id is the stable public identity of the user-visible work candidate
        # and becomes schema_candidate_queue.public_id after acceptance.
        "work_public_id": work_public_id,
        "claim_type": row["claim_type"],
        "title": "" if source_invalidated else row["title"],
        "statement": "" if source_invalidated else row["statement"],
        "trigger": "" if source_invalidated else row["trigger_text"],
        "experience": "" if source_invalidated else row["experience_text"],
        "response": "" if source_invalidated else row["response_text"],
        "short_term_effect": (
            "" if source_invalidated else row["short_term_effect"]),
        "long_term_effect": (
            "" if source_invalidated else row["long_term_effect"]),
        "need": "" if source_invalidated else row["need_text"],
        "counterexample": (
            "" if source_invalidated else row["counterexample_text"]),
        "context": "" if source_invalidated else row["context_label"],
        "status": row["status"],
        "scope": row["scope"],
        "sensitive": bool(row["sensitive"]),
        "schema": (None if source_invalidated else {
            "id": row["schema_key"],
            "label": SCHEMA_CANDIDATE_CATALOG[row["schema_key"]],
        } if row["schema_key"] in SCHEMA_CANDIDATE_CATALOG else None),
        "mode": (None if source_invalidated else {
            "id": row["mode_key"],
            "label": SCHEMA_MODE_CANDIDATE_CATALOG[row["mode_key"]],
        } if row["mode_key"] in SCHEMA_MODE_CANDIDATE_CATALOG else None),
        "source_turn": source_turns[0] if source_turns else None,
        "source_turns": source_turns,
        "hypothesis_notice": ((
            "Kaynak tur artık inceleme kapsamında değil; bu aday "
            "gizlendi ve kullanılamaz.") if source_invalidated else (
            "Bu anlatımda olası {} gördüm; bu erken ve tek anlatıma "
            "dayalı bir hipotezdir, tanı değildir.".format(
                " / ".join(hypothesis_parts)))),
        "decision_state": decision_state,
        "available_decisions": (
            ["accept", "defer", "dismiss"]
            if row["status"] in ("candidate", "deferred")
            and not locked_by_other and not source_invalidated else []),
        "source_invalidated": source_invalidated,
        "invalidated_reason": (
            "private" if row["scope"] in ("private", "excluded")
            or row["sensitive"] else
            "source_no_longer_eligible" if source_invalidated else ""),
        "deferred_for_next_session": deferred,
        "used_for_path": used_for_path,
        "deferred_reason": (
            "active_path" if locked_by_other else
            "user_deferred" if row["status"] == "deferred" else ""),
        "sources": [{
            "message_id": source["message_id"],
            "excerpt": source["excerpt"],
            "created": source["source_created"],
            "review_status": source["review_status"],
        } for source in user_sources],
        "direct_user_evidence": user_sources,
        "counterexamples": counter_sources,
        "evidence_summary": evidence,
        "approved_for_path": bool(
            not source_invalidated
            and
            row["status"] in SCHEMA_PATH_APPROVED_CLAIM_STATUSES
            and row["scope"] not in ("private", "excluded")
            and not row["sensitive"]
            and evidence["accepted_completed"] > 0),
        "created": row["created"],
        "updated": row["updated"],
    }


def schema_path_record_rows(connection, path_id):
    return connection.execute(
        "SELECT kind,value,created FROM schema_path_events WHERE path=? "
        "AND action='record' AND authored_by='user' ORDER BY seq,id",
        (path_id,)).fetchall()


def schema_path_record_values(connection, path_id):
    values = {}
    for row in schema_path_record_rows(connection, path_id):
        values.setdefault(row["kind"], []).append(row["value"])
    return values


def schema_clinical_sync_public(connection, conv):
    """Public, provider-independent consent for syncing approved deep work."""
    row = connection.execute(
        "SELECT schema_clinical_sync_enabled,"
        "schema_clinical_sync_initialized,"
        "schema_clinical_sync_generation FROM session_meta WHERE conv=?",
        (conv["id"],)).fetchone()
    preference_enabled = bool(row and row["schema_clinical_sync_enabled"])
    initialized = bool(row and row["schema_clinical_sync_initialized"])
    generation = max(0, int(
        row["schema_clinical_sync_generation"] if row else 0))
    enabled = bool(preference_enabled and initialized)
    if conv["is_guest"]:
        reason = "guest_scope"
    elif conv["safety_hold"]:
        reason = "safety_hold"
    elif conv["ended"] or conv["archived_at"]:
        reason = "conversation_closed"
    elif preference_enabled and not initialized:
        reason = "device_confirmation_required"
    else:
        reason = "enabled" if enabled else "disabled"
    return {
        "enabled": enabled,
        "preference_enabled": preference_enabled,
        "initialized": initialized,
        "generation": generation,
        "pending_device_confirmation": bool(
            preference_enabled and not initialized),
        "can_enable": reason in (
            "enabled", "disabled", "device_confirmation_required"),
        "reason": reason,
        "notice": (
            "Onaylanmış Şema Çalışma Yolu bu görüşmeye bağlı cihazlar "
            "arasında eşitleniyor. Ham model analizleri ve sağlayıcı izni "
            "bu kapsama girmez."
            if enabled else
            "Başka bir cihazdaki eşitleme tercihi burada henüz onaylanmadı. "
            "Bu cihaz klinik içeriği göndermeden veya uygulamadan önce açık "
            "yerel onay ister."
            if preference_enabled and not initialized else
            "Bu çalışma yalnız bu cihazda tutuluyor. Cihazlar arası klinik "
            "eşitleme, model sağlayıcısı izninden ayrı ve isteğe bağlıdır."),
    }


def schema_clinical_generation(connection, conv_id):
    row = connection.execute(
        "SELECT schema_clinical_sync_generation FROM session_meta WHERE conv=?",
        (conv_id,)).fetchone()
    return max(0, int(
        row["schema_clinical_sync_generation"] if row else 0))


def rekey_schema_v4_path_generation(connection, path_id, generation):
    """Move one still-local path to a fresh, non-revivable sync generation.

    Withdrawal tombstones the previous public ids.  A later explicit enable
    therefore rekeys only the path that can still be continued; completed old
    paths retain their withdrawn generation and never silently reappear.
    """
    generation = int(generation)
    path = connection.execute(
        "SELECT p.*,v.public_id AS conv_public FROM schema_paths p "
        "JOIN conversations v ON v.id=p.conv WHERE p.id=? AND "
        "p.flow_version>=4", (path_id,)).fetchone()
    if not path or int(path["path_sequence"] or 0) < 1:
        return None
    new_path_public = _schema_natural_public_id(
        "path", path["conv_public"], generation, path["path_sequence"])
    old_to_new = {str(path["public_id"] or ""): new_path_public}
    connection.execute(
        "UPDATE schema_paths SET public_id=?,clinical_generation=?,updated=? "
        "WHERE id=?",
        (new_path_public, generation, now(), path_id))
    connection.execute(
        "UPDATE schema_candidate_queue SET clinical_generation=?,updated=? "
        "WHERE path=?", (generation, now(), path_id))
    connection.execute(
        "UPDATE message_meta_events SET clinical_generation=?,updated=? "
        "WHERE path=?", (generation, now(), path_id))

    for table in (
            "schema_candidate_queue", "schema_focus_checks",
            "schema_path_steps", "schema_path_techniques", "schema_origin",
            "schema_growth", "healthy_adult_marks", "message_meta_events",
            "schema_transfer_records"):
        rows = connection.execute(
            "SELECT * FROM {} WHERE {}=? ORDER BY id".format(
                table, "path"), (path_id,)).fetchall()
        for row in rows:
            old = str(row["public_id"] or "")
            natural = _schema_v4_natural_row_id(connection, table, row)
            if not natural:
                continue
            connection.execute(
                "UPDATE {} SET public_id=? WHERE id=?".format(table),
                (natural, row["id"]))
            if old:
                old_to_new[old] = natural

    focus_public = str(path["focus_candidate_public_id"] or "")
    if focus_public in old_to_new:
        connection.execute(
            "UPDATE schema_paths SET focus_candidate_public_id=? WHERE id=?",
            (old_to_new[focus_public], path_id))
    for old, new in old_to_new.items():
        if old and old != new:
            connection.execute(
                "UPDATE message_meta_events SET artifact_public_id=? "
                "WHERE path=? AND artifact_public_id=?",
                (new, path_id, old))
    return connection.execute(
        "SELECT * FROM schema_paths WHERE id=?", (path_id,)).fetchone()


def schema_path_open_sync_conflict(connection, path):
    """Future-proof hook: absent/empty conflict storage means no conflict."""
    if not path or not str(path["public_id"] or ""):
        return None
    exists = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' "
        "AND name='schema_path_sync_conflicts'").fetchone()
    if not exists:
        return None
    return connection.execute(
        "SELECT * FROM schema_path_sync_conflicts WHERE path_public_id=? "
        "AND status='open' ORDER BY id DESC LIMIT 1",
        (path["public_id"],)).fetchone()


def _schema_message_ref(connection, conv_id, local_id=None, public_id=None,
                        role=None):
    clauses = ["conv=?"]
    params = [conv_id]
    if local_id not in (None, ""):
        if type(local_id) is not int or local_id < 1:
            raise RequestInputError("geçersiz mesaj kimliği")
        clauses.append("id=?")
        params.append(local_id)
    elif public_id:
        value = str(public_id).strip()
        if not TRANSFER_PUBLIC_ID_RE.fullmatch(value):
            raise RequestInputError("geçersiz mesaj genel kimliği")
        clauses.append("public_id=?")
        params.append(value)
    else:
        raise RequestInputError("mesaj kaynağı gerekli")
    if role:
        clauses.append("role=?")
        params.append(role)
    return connection.execute(
        "SELECT * FROM messages WHERE " + " AND ".join(clauses),
        params).fetchone()


def schema_exact_source_pair(connection, conv_id, user_message_id=None,
                             assistant_message_id=None,
                             user_message_public_id=None,
                             assistant_message_public_id=None):
    """Resolve one still-safe authoritative pair by local or public ids."""
    user = _schema_message_ref(
        connection, conv_id, user_message_id, user_message_public_id, "user")
    assistant = _schema_message_ref(
        connection, conv_id, assistant_message_id,
        assistant_message_public_id, "assistant")
    if user is None or assistant is None:
        raise RequestInputError(
            "Şema adımının kaynak mesaj çifti bulunamadı", 409,
            "schema_source_invalid")
    pair, error = completed_normal_turn(connection, conv_id, user["id"])
    if not pair:
        # ``chat_requests`` is device-local delivery/job state and is not
        # synchronized. A receiving device may nevertheless trust this exact
        # pair after both immutable messages were installed through the live,
        # authenticated sync projection. Keep the fallback narrower than
        # ``completed_normal_turn`` so imported rows never enter local turn
        # analysis or Living Map scans. A local/failed request always wins,
        # and arbitrary message rows without two live sync identities remain
        # ineligible.
        sync_table = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='sync_records'").fetchone()
        if sync_table:
            pair = connection.execute(
                "SELECT u.conv,u.id AS user_message,a.id AS "
                "assistant_message,'completed' AS status,"
                "u.role AS user_role,u.delivery_status AS user_delivery,"
                "u.content AS user_content,u.created AS user_created,"
                "a.role AS assistant_role,a.delivery_status AS "
                "assistant_delivery,a.content AS assistant_content,"
                "a.created AS assistant_created,0 AS safety_turn "
                "FROM messages u JOIN messages a ON a.conv=u.conv "
                "JOIN sync_records su ON su.record_type='message' "
                "AND su.local_id=u.id AND su.public_id=u.public_id "
                "AND su.deleted_at IS NULL "
                "JOIN sync_records sa ON sa.record_type='message' "
                "AND sa.local_id=a.id AND sa.public_id=a.public_id "
                "AND sa.deleted_at IS NULL "
                "WHERE u.conv=? AND u.id=? AND a.id=? "
                "AND u.role='user' AND a.role='assistant' "
                "AND u.delivery_status='completed' "
                "AND a.delivery_status='completed' "
                "AND u.turn_pair_public_id=a.turn_pair_public_id "
                "AND length(u.turn_pair_public_id)=32 "
                "AND u.turn_pair_public_id NOT GLOB '*[^0-9a-f]*' "
                "AND NOT EXISTS(SELECT 1 FROM chat_requests r "
                "WHERE r.conv=u.conv AND r.user_message=u.id) "
                "AND NOT EXISTS(SELECT 1 FROM safety_events s "
                "WHERE s.conv=u.conv AND s.source_message=u.id)",
                (conv_id, user["id"], assistant["id"])).fetchone()
    if not pair or int(pair["assistant_message"] or 0) != assistant["id"]:
        raise RequestInputError(
            "Şema adımının kaynak mesaj çifti artık tamamlanmış ve güvenli değil",
            409, "schema_source_invalid")
    return {
        "user_message_id": int(user["id"]),
        "user_message_public_id": str(user["public_id"] or ""),
        "assistant_message_id": int(assistant["id"]),
        "assistant_message_public_id": str(assistant["public_id"] or ""),
        "user_content": str(pair["user_content"] or ""),
        "assistant_content": str(pair["assistant_content"] or ""),
    }


def schema_pair_from_data(connection, conv_id, data):
    return schema_exact_source_pair(
        connection, conv_id,
        data.get("source_user_message_id"),
        data.get("source_assistant_message_id"),
        data.get("source_user_message_public_id"),
        data.get("source_assistant_message_public_id"))


def schema_trigger_pair_from_data(connection, conv_id, data):
    """Resolve and pin the historical present-trigger's exact safe pair."""
    user = _schema_message_ref(
        connection, conv_id,
        data.get("trigger_source_user_message_id"),
        data.get("trigger_source_user_message_public_id"), "user")
    completed, _error = completed_normal_turn(
        connection, conv_id, user["id"] if user else None)
    if not completed:
        raise RequestInputError(
            "Bugünkü tetikleyicinin tamamlanmış güvenli mesaj çifti "
            "bulunamadı", 409, "schema_source_invalid")
    pair = schema_exact_source_pair(
        connection, conv_id, user["id"], completed["assistant_message"])
    supplied_assistant = any(data.get(key) not in (None, "") for key in (
        "trigger_source_assistant_message_id",
        "trigger_source_assistant_message_public_id"))
    if supplied_assistant:
        assistant = _schema_message_ref(
            connection, conv_id,
            data.get("trigger_source_assistant_message_id"),
            data.get("trigger_source_assistant_message_public_id"),
            "assistant")
        if not assistant or int(assistant["id"]) != int(
                pair["assistant_message_id"]):
            raise RequestInputError(
                "Bugünkü tetikleyicinin yardımcı yanıt kaynağı uyuşmuyor",
                409, "schema_source_invalid")
    return pair


def schema_claim_primary_pair(connection, conv_id, claim_id):
    row = connection.execute(
        "SELECT m.id AS user_id,m.public_id AS user_public_id,a.id AS "
        "assistant_id,a.public_id AS assistant_public_id,m.content AS quote "
        "FROM psych_claim_evidence e "
        "JOIN psych_observations o ON o.id=e.observation AND o.conv=? "
        "JOIN messages m ON m.id=o.source_message AND m.conv=o.conv "
        "JOIN chat_requests q ON q.conv=o.conv AND q.user_message=m.id "
        "AND q.status='completed' "
        "JOIN messages a ON a.id=q.assistant_message AND a.conv=q.conv "
        "WHERE e.claim=? AND e.relation='supports' "
        "AND e.review_status='accepted' AND m.role='user' "
        "AND m.delivery_status='completed' AND a.role='assistant' "
        "AND a.delivery_status='completed' "
        "AND NOT EXISTS(SELECT 1 FROM safety_events s WHERE s.conv=q.conv "
        "AND s.source_message=q.user_message) ORDER BY m.id,e.id LIMIT 1",
        (conv_id, claim_id)).fetchone()
    if row is None:
        return None
    try:
        return schema_exact_source_pair(
            connection, conv_id, row["user_id"], row["assistant_id"])
    except RequestInputError:
        return None


def schema_latest_safe_source_pair(connection, conv_id):
    """Return the newest real, completed and still-safe conversation pair.

    A candidate may deliberately remain visible while newer listening turns
    arrive. Accepting that older evidence must not attach the first hidden
    chat binding to an older assistant bubble: native clients anchor the
    controlled continuation beneath the latest real Kerem response. The
    candidate/claim lineage remains separate and continues to point at the
    evidence pair that produced it.
    """
    row = connection.execute(
        "SELECT r.user_message,r.assistant_message "
        "FROM chat_requests r "
        "JOIN messages u ON u.id=r.user_message AND u.conv=r.conv "
        "AND u.role='user' AND u.delivery_status='completed' "
        "JOIN messages a ON a.id=r.assistant_message AND a.conv=r.conv "
        "AND a.role='assistant' AND a.delivery_status='completed' "
        "WHERE r.conv=? AND r.status='completed' "
        "AND NOT EXISTS(SELECT 1 FROM safety_events s WHERE s.conv=r.conv "
        "AND s.source_message=r.user_message) "
        "ORDER BY a.id DESC,r.created DESC,r.request_id DESC LIMIT 1",
        (conv_id,)).fetchone()
    if row is None:
        raise RequestInputError(
            "Şema sohbetinin bağlanacağı güvenli Kerem yanıtı bulunamadı",
            409, "schema_source_invalid")
    return schema_exact_source_pair(
        connection, conv_id, row["user_message"], row["assistant_message"])


def schema_candidate_queue_row(connection, conv_id, reference,
                               path_id=None):
    clauses = ["conv=?"]
    params = [conv_id]
    if type(reference) is int and reference > 0:
        clauses.append("id=?")
        params.append(reference)
    elif isinstance(reference, str) and TRANSFER_PUBLIC_ID_RE.fullmatch(
            reference.strip()):
        clauses.append("public_id=?")
        params.append(reference.strip())
    else:
        return None
    if path_id is not None:
        clauses.append("path=?")
        params.append(path_id)
    return connection.execute(
        "SELECT * FROM schema_candidate_queue WHERE " +
        " AND ".join(clauses), params).fetchone()


def schema_candidate_label(row):
    parts = []
    if row and row["schema_key"] in SCHEMA_CANDIDATE_CATALOG:
        parts.append(SCHEMA_CANDIDATE_CATALOG[row["schema_key"]])
    if row and row["mode_key"] in SCHEMA_MODE_CANDIDATE_CATALOG:
        parts.append(SCHEMA_MODE_CANDIDATE_CATALOG[row["mode_key"]] + " modu")
    return " / ".join(parts) or "Çalışma olasılığı"


def schema_candidate_queue_public(connection, row):
    if row is None:
        return None
    source = connection.execute(
        "SELECT content,public_id FROM messages WHERE id=? AND conv=? "
        "AND role='user'",
        (row["source_user_message"], row["conv"])).fetchone()
    assistant = connection.execute(
        "SELECT public_id FROM messages WHERE id=? AND conv=? "
        "AND role='assistant'",
        (row["source_assistant_message"], row["conv"])).fetchone()
    return {
        "id": int(row["id"]),
        "public_id": str(row["public_id"] or ""),
        "clinical_generation": int(row["clinical_generation"] or 0),
        "path_id": row["path"],
        "claim_id": row["claim"],
        "suggestion_id": row["suggestion"],
        "schema_key": row["schema_key"],
        "mode_key": row["mode_key"],
        "label": schema_candidate_label(row),
        "evidence": row["evidence"],
        "burden": row["burden"],
        "impact": row["impact"],
        "priority": row["priority"],
        "status": row["status"],
        "source": {
            "user_message_id": int(row["source_user_message"]),
            "user_message_public_id": str(
                source["public_id"] or "") if source else "",
            "assistant_message_id": int(row["source_assistant_message"]),
            "assistant_message_public_id": str(
                assistant["public_id"] or "") if assistant else "",
            "quote": clip_context_text(
                source["content"] if source else "", 320),
        },
        "revision": int(row["revision"] or 0),
        "created": row["created"], "updated": row["updated"],
    }


def ensure_schema_candidate_queue_for_claim(connection, conv_id, claim_id,
                                            path_id=None, preferred=False):
    claim = schema_candidate_row(connection, conv_id, claim_id)
    if claim is None:
        return None
    pair = schema_claim_primary_pair(connection, conv_id, claim_id)
    if pair is None:
        return None
    schema_key = (claim["schema_key"]
                  if claim["schema_key"] in SCHEMA_CANDIDATE_CATALOG else "")
    mode_key = (claim["mode_key"]
                if claim["mode_key"] in SCHEMA_MODE_CANDIDATE_CATALOG else "")
    if not schema_key and not mode_key:
        return None
    stamp = now()
    current_order = connection.execute(
        "SELECT COALESCE(MAX(sort_order),0)+1 AS n FROM "
        "schema_candidate_queue WHERE conv=?",
        (conv_id,)).fetchone()["n"]
    conv_public = connection.execute(
        "SELECT public_id FROM conversations WHERE id=?", (conv_id,)
    ).fetchone()["public_id"]
    if path_id:
        generation_row = connection.execute(
            "SELECT clinical_generation FROM schema_paths WHERE id=? AND conv=?",
            (path_id, conv_id)).fetchone()
        generation = int(generation_row["clinical_generation"] or 0) \
            if generation_row else schema_clinical_generation(
                connection, conv_id)
    else:
        generation = schema_clinical_generation(connection, conv_id)
    public_id = _schema_natural_public_id(
        "candidate", conv_public, generation, pair["user_message_public_id"],
        pair["assistant_message_public_id"], schema_key or "-",
        mode_key or "-")
    connection.execute(
        "INSERT OR IGNORE INTO schema_candidate_queue("
        "public_id,conv,path,clinical_generation,claim,source_user_message,"
        "source_assistant_message,schema_key,mode_key,evidence,status,"
        "sort_order,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,'offered',?,?,?)",
        (public_id, conv_id, path_id, generation, claim_id,
         pair["user_message_id"],
         pair["assistant_message_id"], schema_key, mode_key,
         clip_context_text(pair["user_content"], 700),
         -100 if preferred else int(current_order or 1), stamp, stamp))
    row = connection.execute(
        "SELECT * FROM schema_candidate_queue WHERE conv=? "
        "AND source_user_message=? AND source_assistant_message=? "
        "AND schema_key=? AND mode_key=?",
        (conv_id, pair["user_message_id"], pair["assistant_message_id"],
         schema_key, mode_key)).fetchone()
    if row and path_id is not None and row["path"] != path_id:
        connection.execute(
            "UPDATE schema_candidate_queue SET path=?,status='offered',"
            "clinical_generation=?,sort_order=?,updated=? WHERE id=?",
            (path_id, generation,
             -100 if preferred else row["sort_order"], stamp, row["id"]))
        row = connection.execute(
            "SELECT * FROM schema_candidate_queue WHERE id=?",
            (row["id"],)).fetchone()
    return row


def schema_seed_candidate_queue(connection, conv_id, path_id,
                                preferred_claim_id=None):
    claim_rows = connection.execute(
        "SELECT id FROM psych_claims WHERE source_conv=? "
        "AND therapist='young' AND claim_type='schema_hypothesis' "
        "AND status IN ('confirmed','partial','contextual','candidate',"
        "'deferred') AND scope NOT IN ('private','excluded') AND sensitive=0 "
        "ORDER BY CASE WHEN id=? THEN 0 ELSE 1 END,updated DESC,id DESC",
        (conv_id, int(preferred_claim_id or 0))).fetchall()
    seeded = []
    for claim in claim_rows:
        row = ensure_schema_candidate_queue_for_claim(
            connection, conv_id, claim["id"], path_id,
            preferred=(claim["id"] == preferred_claim_id))
        if row and row["id"] not in {item["id"] for item in seeded}:
            seeded.append(row)
    return seeded


def schema_current_candidate_row(connection, path):
    if not path:
        return None
    if path["focus_candidate_public_id"]:
        row = connection.execute(
            "SELECT * FROM schema_candidate_queue WHERE path=? "
            "AND public_id=? LIMIT 1",
            (path["id"], path["focus_candidate_public_id"])).fetchone()
        if row:
            return row
    statuses = (
        ("accepted", "selected")
        if path["step"] not in ("candidate_review", "listen")
        else ("offered", "accepted"))
    return connection.execute(
        "SELECT * FROM schema_candidate_queue WHERE path=? "
        "AND status IN ({}) ORDER BY sort_order,id LIMIT 1".format(
            ",".join("?" for _ in statuses)),
        (path["id"], *statuses)).fetchone()


def schema_v4_step_position(step):
    stage = SCHEMA_PATH_V4_STEP_STAGE.get(step, "listen")
    stages = {
        "listen": ("listen", "candidate_review", "current_impact",
                   "variable_check", "focus_confirm"),
        "depth": ("method_select", "method_confirm", "origin_or_unknown",
                  "imagery_precheck", "imagery_work", "mode_dialogue",
                  "reparent_or_chair_precheck",
                  "reparent_or_chair_work", "grounding_review"),
        "integrate": ("healthy_adult_voice", "age_ladder",
                      "environment_rescript", "present_transfer",
                      "optional_practice", "followup"),
        "complete": ("complete",),
    }
    sequence = stages[stage]
    return stage, sequence.index(step) + 1 if step in sequence else 1, len(sequence)


def schema_v4_progress(path):
    step = str(path["step"] or "listen") if path else "listen"
    stage, number, total = schema_v4_step_position(step)
    return {
        "stage_number": {"listen": 1, "depth": 2,
                         "integrate": 3, "complete": 3}[stage],
        "stage_total": 3,
        "step_number": number,
        "step_total": total,
        "label": SCHEMA_PATH_V4_STEP_LABELS.get(step, "Şema çalışması"),
    }


SCHEMA_PATH_V5_STEP_LABELS = {
    "listen": "Dinleme", "candidate_review": "Çalışma izni",
    "variable_explore": "Varsayımsal değişken keşfi",
    "origin_sequence": "Kökeni yalnız hatırlandığı kadar anlama",
    "imagery_work": "İmgeleme çalışması",
    "mode_dialogue": "Sandalye diyaloğu",
    "reparent_or_chair_work": "Mevcut yöntem çalışması",
    "grounding_review": "Şimdiye dönüş",
    "healthy_adult_voice": "Sağlıklı Yetişkin sesi",
    "age_ladder": "Yaş entegrasyonu",
    "environment_rescript": "Çevreyi yeniden resmetme",
    "present_transfer": "Bugüne taşıma",
    "optional_practice": "İsteğe bağlı pratik",
    "followup": "İzlem", "complete": "Tamamlandı",
}


def schema_v5_progress(path):
    step = str(path["step"] or "listen") if path else "listen"
    stage = SCHEMA_PATH_V5_STEP_STAGE.get(step, "listen")
    stage_steps = tuple(
        item for item in SCHEMA_PATH_V5_STEPS
        if SCHEMA_PATH_V5_STEP_STAGE[item] == stage)
    return {
        "stage_number": SCHEMA_PATH_V5_STAGES.index(stage) + 1,
        "stage_total": len(SCHEMA_PATH_V5_STAGES),
        "step_number": stage_steps.index(step) + 1 if step in stage_steps else 1,
        "step_total": len(stage_steps),
        "label": SCHEMA_PATH_V5_STEP_LABELS.get(step, "Şema çalışması"),
    }


def schema_message_meta_insert(connection, event_key, conv_id, message_id,
                               pair, kind, title, summary, path=None,
                               step="", artifact_type="", artifact_id=None,
                               artifact_public_id="", payload=None,
                               actions=None):
    stamp = now()
    owner_public = str(path["public_id"] or "") if path else str(
        connection.execute(
            "SELECT public_id FROM conversations WHERE id=?", (conv_id,)
        ).fetchone()["public_id"] or "")
    generation = (int(path["clinical_generation"] or 0) if path else
                  schema_clinical_generation(connection, conv_id))
    stored_event_key = (str(event_key) if path else
                        "g{}:{}".format(generation, event_key))
    public_id = (_schema_natural_public_id(
        "meta", owner_public, stored_event_key) if path else
        _schema_natural_public_id(
            "meta-local", owner_public, generation, stored_event_key))
    connection.execute(
        "INSERT OR IGNORE INTO message_meta_events("
        "public_id,event_key,conv,message,clinical_generation,"
        "source_user_message,"
        "source_assistant_message,path,step,kind,status,title,summary,"
        "artifact_type,artifact_id,artifact_public_id,payload_json,"
        "actions_json,created,updated) "
        "VALUES(?,?,?,?,?,?,?, ?,?,?,'active',?,?,?,?,?,?,?,?,?)",
        (public_id, stored_event_key, conv_id, message_id, generation,
         pair["user_message_id"], pair["assistant_message_id"],
         path["id"] if path else None, step, kind, title, summary,
         artifact_type, artifact_id, artifact_public_id,
         json.dumps(payload or {}, ensure_ascii=False, sort_keys=True),
         json.dumps(actions or [], ensure_ascii=False, sort_keys=True),
         stamp, stamp))
    return connection.execute(
        "SELECT * FROM message_meta_events WHERE event_key=?",
        (stored_event_key,)).fetchone()


def public_schema_message_meta(connection, row):
    try:
        payload = json.loads(row["payload_json"] or "{}")
    except (TypeError, ValueError, json.JSONDecodeError):
        payload = {}
    try:
        actions = json.loads(row["actions_json"] or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        actions = []
    status = str(row["status"] or "invalidated")
    pair, _ = completed_normal_turn(
        connection, row["conv"], row["source_user_message"])
    if (not pair or int(pair["assistant_message"] or 0) !=
            int(row["source_assistant_message"] or 0)):
        status, actions = "invalidated", []
    path_public = ""
    path_row = None
    if row["path"]:
        path_row = connection.execute(
            "SELECT * FROM schema_paths WHERE id=?",
            (row["path"],)).fetchone()
        path_public = str(path_row["public_id"] or "") if path_row else ""
    if (status in ("active", "private") and row["kind"] == "map_update"
            and row["artifact_id"]):
        claim = connection.execute(
            "SELECT id,scope,status,sensitive FROM psych_claims WHERE id=?",
            (row["artifact_id"],)).fetchone()
        if (claim and not claim["sensitive"]
                and claim["status"] not in ("rejected", "excluded")):
            base_payload = {
                "meta_event_id": int(row["id"]),
                "meta_event_public_id": str(row["public_id"] or ""),
                "clinical_generation": int(
                    row["clinical_generation"] or 0),
                "source_user_message_id": int(row["source_user_message"]),
                "source_assistant_message_id": int(
                    row["source_assistant_message"]),
            }
            if path_row:
                base_payload.update({
                    "path_id": int(path_row["id"]),
                    "path_public_id": path_public,
                    "expected_revision": int(path_row["revision"] or 0),
                })
            actions = [{
                "id": "map-undo-{}".format(row["public_id"]),
                "action": "undo_map_update", "label": "Geri al",
                "style": "secondary", "requires_confirm": False,
                "payload": dict(base_payload),
            }, {
                "id": "map-edit-{}".format(row["public_id"]),
                "action": "edit_map_update", "label": "Düzenle",
                "style": "secondary", "requires_confirm": False,
                # The client replaces this user-authored value before POST;
                # retaining the current text makes the action executable and
                # idempotent even on clients without an edit sheet.
                "payload": {**base_payload, "note": row["summary"]},
            }]
            if status == "active" and claim["scope"] != "private":
                actions.insert(1, {
                    "id": "map-private-{}".format(row["public_id"]),
                    "action": "make_map_update_private",
                    "label": "Özel yap", "style": "secondary",
                    "requires_confirm": True,
                    "payload": dict(base_payload),
                })
        else:
            actions = []
    return {
        "id": int(row["id"]), "public_id": str(row["public_id"] or ""),
        "clinical_generation": int(row["clinical_generation"] or 0),
        "kind": row["kind"], "status": status,
        "message_id": int(row["message"]),
        "source_user_message_id": int(row["source_user_message"]),
        "source_assistant_message_id": int(row["source_assistant_message"]),
        "path_id": row["path"], "path_public_id": path_public,
        "expected_revision": (
            int(path_row["revision"] or 0) if path_row else None),
        "stage": SCHEMA_PATH_V4_STEP_STAGE.get(row["step"], ""),
        "step": row["step"], "title": row["title"],
        "summary": row["summary"], "payload": payload,
        # A private note remains editable/removable on its owning device;
        # only the action that *makes* it private disappears above.
        "actions": actions if status in ("active", "private") else [],
        "created": row["created"], "updated": row["updated"],
    }


def schema_message_meta_payload(connection, conv_id, message_id=None,
                                limit=80):
    sql = "SELECT * FROM message_meta_events WHERE conv=? "
    params = [conv_id]
    if message_id is not None:
        sql += "AND message=? "
        params.append(message_id)
    sql += "ORDER BY id DESC LIMIT ?"
    params.append(int(limit))
    rows = connection.execute(sql, params).fetchall()
    return [public_schema_message_meta(connection, row)
            for row in reversed(rows)]


def schema_v4_step_row(connection, path, step=None):
    return connection.execute(
        "SELECT * FROM schema_path_steps WHERE path=? AND step=?",
        (path["id"], step or path["step"])).fetchone()


