    def psych_prep_summary_text(self, sections, safety_plan_text,
                                include_sections=None, measures_text=""):
        """Tek sayfalık, yazdırılabilir hazırlık özeti.

        Yalnız kullanıcının doldurduğu ve paylaşmak istediği bölümler
        girer; boş bölümler "değerlendirilemedi" olarak işaretlenir.
        Kaynaklar ayrı başlıklarda durur: kullanıcı beyanı ve ölçüm
        sonucu. Model yorumu üretilmediği için "AI yorumu" bölümü
        bilinçli olarak yoktur."""
        lines = [
            "PSİKİYATRİ GÖRÜŞMESİNE HAZIRLIK ÖZETİ",
            "Bu belge yalnız kullanıcının kendi girdiği bilgilerden oluşur; "
            "tanı veya ilaç önerisi içermez. Hazırlanma: {}".format(now()),
            "",
        ]
        for key, title in PSYCH_PREP_SECTIONS:
            if include_sections is not None and key not in include_sections:
                continue
            content = str(sections.get(key) or "").strip()
            lines.append(title + " — kullanıcı beyanı")
            lines.append(
                content if content else
                "Değerlendirilemedi: bu bölüm doldurulmadı.")
            lines.append("")
        if measures_text:
            lines.append("Ölçüm sonuçları — kullanıcı özbildirimi")
            lines.append(measures_text)
            lines.append("")
        lines.append("Güvenlik planı")
        lines.append(
            safety_plan_text if safety_plan_text else
            "Değerlendirilemedi: güvenlik planı kaydedilmemiş.")
        lines.append("")
        lines.append("Uygulamanın değerlendiremediği alanlar")
        for area in PSYCH_PREP_UNEVALUABLE:
            lines.append("- {} (değerlendirilemedi)".format(area))
        lines.append("")
        lines.append(
            "Bu belge tıbbi kayıt değil, görüşmeye hazırlık notudur. "
            "Acil tehlike için 112 veya en yakın acil servis.")
        return "\n".join(lines)

    def api_process(self):
        """Bitmiş bir görüşmenin seans sonrası işlemesini elle tetikler.

        Seansı bitirmek yerine (veya bitişteki iş başarısız olduktan sonra)
        kullanıcı bu uçla not, formülasyon, özet, Yaşayan Harita adayları,
        mektup ve kavramların eksik olanlarını yeniden ürettirebilir.
        Var olan iş parçaları üretim zincirindeki korumalarla atlanır;
        yani çağrı tekrarlandığında yalnızca eksikler işlenir.
        """
        data = self.read_json()
        try:
            cid = int(data.get("conv_id") or data.get("id"))
        except (TypeError, ValueError):
            raise RequestInputError("geçersiz görüşme")
        with db() as c:
            conv = c.execute("SELECT * FROM conversations WHERE id=?",
                             (cid,)).fetchone()
        if not conv:
            self.send_json({"error": "görüşme yok"}, 404)
            return
        if not conv["ended"]:
            self.send_json({
                "error": "yalnızca bitmiş görüşmeler işlenebilir"}, 409)
            return
        if conv["submode"] in ("supervizyon", "konsey"):
            self.send_json({
                "error": "bu görüşme türü işlenemez"}, 409)
            return
        job_id = create_job("session_postprocess", cid)
        start_job_worker()
        enqueue_job(job_id, data_generation())
        self.send_json({
            "ok": True, "queued": True, "job_id": job_id,
            "message": "Seans işleme kuyruğa alındı.",
        })

    def api_new(self):
        data = self.read_json()
        mode = data.get("mode", "terapi")
        if mode not in ("terapi", "ders"):
            mode = "terapi"
        submode = data.get("submode")
        therapist = str(data.get("therapist") or "freud")
        case_id = data.get("case_id") or None
        case = case_record(case_id) if case_id else None
        if case_id and not case:
            self.send_json({"error": "vaka bulunamadı"}, 400)
            return
        if case:
            mode, submode, therapist = "ders", "vaka", case["therapist"]
        if not known_master(therapist):
            self.send_json({"error": "geçersiz usta"}, 400)
            return
        if is_philosopher(therapist) and mode != "ders":
            self.send_json({
                "error": "felsefeciler yalnız felsefi diyalog/ders açabilir"
            }, 400)
            return
        if (is_philosopher(therapist) and
                submode not in (None, "", "serbest", "mufredat", "vaka",
                                "kaynakli")):
            self.send_json({"error": "geçersiz felsefe alt modu"}, 400)
            return
        source_mode = 1 if data.get("source_mode") else 0
        map_node_id = str(data.get("map_node_id") or "").strip() or None
        if mode == "terapi" and map_node_id and not therapy_map_node(
                therapist, map_node_id):
            self.send_json({"error": "geçersiz başlangıç harita noktası"},
                           400)
            return
        if mode != "terapi":
            map_node_id = None
        precheck = data.get("precheck")
        precheck_completed = isinstance(precheck, dict)
        is_guest = 1 if guest_mode_enabled() else 0
        # Eski, kapanmış ve işlenmemiş sohbetleri istek içinde modele
        # göndermeyiz; yeni sohbet hemen açılır, telafi işleri kuyruğa girer.
        # Telafi yalnız etkin kapsamın (normal/misafir) görüşmelerini işler.
        with db() as c:
            pending = [r["id"] for r in c.execute(
                "SELECT v.id FROM conversations v WHERE v.mode=? AND "
                "v.therapist=? AND v.ended=1 AND "
                "v.is_guest=? AND "
                "COALESCE(v.submode,'') NOT IN "
                "('supervizyon','konsey') AND "
                "NOT EXISTS(SELECT 1 FROM notes t WHERE t.conv=v.id) AND "
                "((SELECT COUNT(*) FROM messages m WHERE m.conv=v.id) + "
                "(SELECT COUNT(*) FROM chair_turns ct WHERE ct.conv=v.id "
                "AND ct.reverted_at IS NULL)) >= ?",
                (mode, therapist, is_guest, NOTE_MIN_MESSAGES)).fetchall()]
        title = (
            case["title"] if case else
            "Yeni seans" if mode == "terapi" else
            "Yeni felsefi sohbet" if is_philosopher(therapist) else
            "Yeni ders")
        with db() as c:
            cur = c.execute(
                "INSERT INTO conversations(mode, submode, therapist, title, "
                "source_mode,case_id,created,updated,is_guest) "
                "VALUES(?,?,?,?,?,?,?,?,?)",
                (mode, submode, therapist, title, source_mode, case_id,
                 now(), now(), is_guest))
            cid = cur.lastrowid
            if mode == "terapi":
                conv = c.execute(
                    "SELECT * FROM conversations WHERE id=?", (cid,)).fetchone()
                if living_map_autoscan_conversation_eligible(conv):
                    initialize_living_map_autoscan_state(c, cid)
                if not is_coach(therapist):
                    initialize_session_map(
                        c, conv, map_node_id, precheck_completed)
        if isinstance(precheck, dict):
            precheck = dict(precheck)
            precheck["precheck_done"] = True
            try:
                update_session_meta(cid, precheck)
            except (TypeError, ValueError):
                pass
        # Kerem Genç görüşmesinde Şema Terapi *tercihi* hazır gelir; fakat bu
        # cihazdaki sağlayıcı/model için rıza üretmeyiz. Kullanıcı sohbet içi
        # açıklamayı onaylayana kadar etkin mod kapalıdır ve Şema çıkarımı için
        # hiçbir metin modele gönderilmez. Future-only watermark yalnız
        # `set_mode` HTTP eyleminde kurulur.
        if schema_mode_default_on(therapist, mode, submode):
            with db() as c:
                initialize_schema_mode_preference(c, cid)
        queued = []
        for old_cid in pending:
            queued.append(create_job("session_postprocess", old_cid))
        if queued:
            start_job_worker()
            for job_id in queued:
                enqueue_job(job_id)
        opening_node = (
            therapy_map_node(therapist, map_node_id) if map_node_id else None)
        selected_master = master_record(therapist)
        greeting = (
            selected_master.get("greet_terapi", "")
            if mode == "terapi" else
            philosophy_greeting(therapist)
            if is_philosopher(therapist) else
            selected_master.get("greet_ders", ""))
        if opening_node and opening_node["kind"] == "method":
            greeting += (
                "\n\nBugünkü çalışma noktanız: **{}**. Önce bu seçimin "
                "sizin için neye hizmet etmesini istediğini ve sınırlarınızı "
                "netleştirelim; teknik ancak açık onayınızla başlar."
                .format(opening_node["name"]))
        response = {
            "id": cid,
            "title": title,
            "sources": [dict(source) for source in
                        CASE_SOURCE_PACKS.get(case_id or "", [])]
                       if source_mode else [],
            "notes_written": 0, "jobs_queued": len(queued),
            "greeting": greeting,
        }
        if mode == "terapi" and not is_coach(therapist):
            response["map"] = therapy_map_payload(therapist, cid)
        self.send_json(response)

