    def api_refer(self):
        data = self.read_json()
        from_t, to_t = data.get("from"), data.get("to")
        if (from_t not in THERAPISTS or to_t not in THERAPISTS
                or from_t == to_t):
            self.send_json({"error": "geçersiz usta çifti"}, 400)
            return
        generation = data_generation()
        with db() as c:
            notes = list(reversed(c.execute(
                "SELECT * FROM notes WHERE mode='terapi' AND "
                "therapist=? AND approved=1 AND scope NOT IN "
                "('private','excluded') "
                "AND sensitive=0 ORDER BY id DESC LIMIT 8",
                (from_t,)).fetchall()))
            formulation_candidates = c.execute(
                "SELECT * FROM formulations WHERE mode='terapi' AND "
                "therapist=? AND status='approved' AND scope NOT IN "
                "('private','excluded') AND sensitive=0 "
                "AND COALESCE(stale,0)=0 ORDER BY id DESC",
                (from_t,)).fetchall()
            f = next((
                row for row in formulation_candidates
                if formulation_is_prompt_eligible(c, row)
            ), None)
            source_snapshots = {}
            if f:
                formulation_source = referral_source_snapshot(
                    "formulation", f)
                source_snapshots[(
                    "formulation", f["id"])] = formulation_source
                # The formulation text inherits its base versions' evidence.
                # Preserve every such note id even when it is older than the
                # eight raw notes shown to the referral writer.
                for evidence_note in referral_formulation_evidence_rows(
                        c, f["id"]):
                    source_snapshots[(
                        "note", evidence_note["id"]
                    )] = referral_source_snapshot("note", evidence_note)
            for note in notes:
                source_snapshots[(
                    "note", note["id"])] = referral_source_snapshot(
                        "note", note)
        if not notes and not f:
            self.send_json({"error": "gönderen ustanın defteri boş"}, 400)
            return
        corpus = ""
        if f:
            corpus += "FORMÜLASYON ({}):\n{}\n\n---\n\n".format(
                f["created"], f["content"])
        corpus += "\n\n".join("NOT ({}):\n{}".format(
            n["created"], n["content"][:6000])
                              for n in notes)
        try:
            letter = ds_complete([
                {"role": "system", "content": artifact_system_prompt(
                    from_t, "terapi", "meslektaşa sevk mektubu")},
                {"role": "user", "content": REFERRAL_PROMPT.format(
                    to_name=THERAPISTS[to_t]["name"]) + "\n\n---\n\n" +
                 corpus},
            ])
        except Exception as e:
            self.send_json({"error": str(e)}, 502)
            return
        with DATA_WRITE_LOCK:
            if generation != DATA_GENERATION:
                self.send_json(
                    {"error": "veriler değişti; sevki yeniden deneyin"}, 409)
                return
            with db() as c:
                for source in source_snapshots.values():
                    valid, _reason = referral_source_current_state(c, source)
                    if not valid:
                        self.send_json({
                            "error": (
                                "sevk kaynağı değişti; güncel onaylı "
                                "kayıtlarla yeniden deneyin")
                        }, 409)
                        return
                baseline = c.execute(
                    "SELECT COUNT(*) AS n FROM notes WHERE mode='terapi' AND "
                    "therapist=? AND approved=1 AND scope NOT IN "
                    "('private','excluded') AND sensitive=0",
                    (to_t,)).fetchone()["n"]
                stamp = now()
                cursor = c.execute(
                    "INSERT INTO referrals("
                    "from_t,to_t,content,created,baseline_count,status,"
                    "invalidated_at,invalidation_reason,updated) "
                    "VALUES(?,?,?,?,?,'active',NULL,'',?)",
                    (from_t, to_t, letter, stamp, baseline, stamp))
                referral_id = cursor.lastrowid
                for source in source_snapshots.values():
                    c.execute(
                        "INSERT INTO referral_sources("
                        "referral,source_type,source_id,source_fingerprint,"
                        "source_created,source_status,source_scope,"
                        "source_sensitive,created) VALUES(?,?,?,?,?,?,?,?,?)",
                        (
                            referral_id, source["source_type"],
                            source["source_id"],
                            source["source_fingerprint"],
                            source["source_created"],
                            source["source_status"], source["source_scope"],
                            source["source_sensitive"], stamp,
                        ))
                record_referral_event(
                    c, referral_id, "created", "", "active",
                    "user_approved_source_lineage")
                referral = c.execute(
                    "SELECT * FROM referrals WHERE id=?",
                    (referral_id,)).fetchone()
                public = public_referral(
                    c, referral, baseline, mutate=False)
        self.send_json({"letter": letter, "referral": public})

    def api_highlight(self):
        data = self.read_json()
        cid = data.get("conv_id")
        text = (data.get("text") or "").strip()
        if not text:
            self.send_json({"error": "eksik"}, 400)
            return
        with db() as c:
            conv = c.execute("SELECT therapist FROM conversations WHERE id=?",
                             (cid,)).fetchone() if cid else None
            selected = data.get("therapist", "freud")
            therapist = conv["therapist"] if conv else (
                selected if selected in ALL_MASTERS else "freud")
            c.execute("INSERT INTO highlights(conv, therapist, text, context, "
                      "created) VALUES(?,?,?,?,?)",
                      (cid or 0, therapist, text[:600],
                       (data.get("context") or "Karşılaştırma")[:120], now()))
        self.send_json({"ok": True})

    def api_highlight_delete(self):
        data = self.read_json()
        with db() as c:
            c.execute("DELETE FROM highlights WHERE id=?",
                      (data.get("id"),))
        self.send_json({"ok": True})

    def api_duet(self):
        data = self.read_json()
        members = [m for m in (data.get("members") or []) if m in THERAPISTS]
        text = (data.get("text") or "").strip()
        if len(members) != 2 or not text:
            self.send_json({"error": "iki usta ve bir soru gerekli"}, 400)
            return
        safety = user_text_safety_gate(text, context="duet")
        if safety["detected"]:
            self.send_json({
                "crisis": True, "safety": safety,
                "message": safety["message"], "answers": [],
            })
            return
        results = {}
        def ask(tid):
            try:
                results[tid] = ds_complete([
                    {"role": "system", "content": artifact_system_prompt(
                        tid, "ders", "iki usta karşılaştırma yanıtı")},
                    {"role": "user", "content": DUET_PROMPT + "\n\nSoru: " +
                     text},
                ], max_tokens=3000)
            except Exception as e:
                results[tid] = "(yanıt alınamadı: {})".format(e)
        threads = [threading.Thread(target=ask, args=(m,)) for m in members]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        self.send_json({"answers": [
            {"therapist": m, "answer": results.get(m, "")} for m in members]})

    def api_triage(self):
        data = self.read_json()
        text = (data.get("text") or "").strip()
        if not text:
            self.send_json({"error": "boş"}, 400)
            return
        safety = user_text_safety_gate(
            text, context="approach_discovery")
        if safety["detected"]:
            self.send_json({
                "crisis": True, "safety": safety,
                "message": safety["message"],
                "answer": safety["message"],
            })
            return
        catalog = "\n".join(
            "- {} — {} ({}): «{}»".format(t["name"], t["school"], t["sub"],
                                          t["quote"])
            for t in THERAPISTS.values())
        try:
            answer = ds_complete([
                {"role": "system",
                 "content": TRIAGE_PROMPT.format(catalog=catalog) +
                 "\n\nTürkçe yaz. Kısa tut."},
                {"role": "user", "content": text},
            ], max_tokens=3000)
        except Exception as e:
            self.send_json({"error": str(e)}, 502)
            return
        self.send_json({"answer": answer})

    def api_dream_analyze(self):
        data = self.read_json()
        therapist = data.get("therapist", "freud")
        if therapist not in THERAPISTS:
            therapist = "freud"
        guest = guest_mode_enabled()
        generation = data_generation()
        with db() as c:
            rows = list(reversed(c.execute(
                "SELECT m.content, m.created FROM messages m "
                "JOIN conversations v ON v.id=m.conv "
                "WHERE m.role='user' AND m.content LIKE '🌙 [Rüya]%' "
                "AND v.therapist=? AND v.is_guest=? "
                "ORDER BY m.id DESC LIMIT 40",
                (therapist, 1 if guest else 0)).fetchall()))
        if not rows:
            self.send_json({"error": "defterde hiç rüya yok"}, 400)
            return
        safety = user_text_safety_gate(
            "\n\n".join(str(r["content"] or "") for r in rows),
            context="dream_analysis")
        if safety["detected"]:
            self.send_json({
                "crisis": True, "safety": safety,
                "message": safety["message"],
                "answer": safety["message"],
            })
            return
        corpus = "\n\n".join("RÜYA ({}):\n{}".format(
            r["created"],
            r["content"].replace("🌙 [Rüya]", "").strip()[:4000])
            for r in rows)[-60000:]
        try:
            answer = ds_complete([
                {"role": "system", "content": artifact_system_prompt(
                    therapist, "terapi", "rüya motifleri değerlendirmesi")},
                {"role": "user",
                 "content": DREAM_ANALYSIS_PROMPT + "\n\n---\n\n" + corpus},
            ])
        except Exception as e:
            self.send_json({"error": str(e)}, 502)
            return
        with DATA_WRITE_LOCK:
            if generation != DATA_GENERATION:
                self.send_json(
                    {"error": "veriler değişti; analizi yeniden deneyin"}, 409)
                return
            with db() as c:
                c.execute("INSERT INTO settings(key, value) VALUES(?,?) "
                          "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                          (("dreamlens_guest_" if guest else "dreamlens_")
                           + therapist,
                           "({}) {}".format(now(), answer)))
        self.send_json({"answer": answer})

    def api_supervise(self):
        data = self.read_json()
        src_id = data.get("source_id")
        generation = data_generation()
        with db() as c:
            src = c.execute("SELECT * FROM conversations WHERE id=?",
                            (src_id,)).fetchone()
            has_job = (c.execute(
                "SELECT 1 FROM jobs WHERE conv=? AND "
                "kind='session_postprocess' LIMIT 1",
                (src_id,)).fetchone() if src else None)
        if src is None or src["mode"] != "terapi" or not src["ended"]:
            self.send_json({"error": "bitmiş kaynak seans bulunamadı"}, 400)
            return
        if not conversation_matches_scope(src):
            self.send_json({"error": "bitmiş kaynak seans bulunamadı"}, 400)
            return
        with DATA_WRITE_LOCK:
            if generation != DATA_GENERATION:
                self.send_json(
                    {"error": "kaynak seans değişti; yeniden deneyin"}, 409)
                return
            with db() as c:
                if not conversation_is_live(c, src_id):
                    self.send_json({"error": "kaynak seans bulunamadı"}, 404)
                    return
                cur = c.execute(
                    "INSERT INTO conversations(mode, submode, therapist, title, "
                    "source, created, updated, is_guest) "
                    "VALUES('ders','supervizyon',?,?,?,?,?,?)",
                    (src["therapist"], "🎓 Süpervizyon: " + src["title"],
                     src_id, now(), now(),
                     1 if guest_mode_enabled() else 0))
                cid = cur.lastrowid
        job_id = None
        if not has_job:
            job_id = create_job("session_postprocess", src_id)
            start_job_worker()
            enqueue_job(job_id)
        self.send_json({"id": cid, "job_id": job_id})

    def api_adhd_tus_get(self):
        query = self.query()
        search = str(query.get("q") or "").strip()
        if len(search) > 80:
            raise RequestInputError("TUS katalog filtresi çok uzun")
        with db() as c:
            conv = open_adhd_conversation(
                c, query.get("conv_id"), allow_safety_hold=True)
            payload = adhd_tus_payload(
                c, conv, load_adhd_tus_catalog(), query=search)
        self.send_json(payload)

